from dataclasses import dataclass
from datetime import datetime


class PromotionExpiredError(Exception):
    def __init__(self, code):
        super().__init__(f"Promotion {code} has expired")
        self.code = code


@dataclass
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


def checkout_total(subtotal_cents, promotion, now):
    """Total in cents. Expired promotions are rejected (policy pending product decision)."""
    if promotion is None:
        return subtotal_cents
    if now >= promotion.expires_at:
        raise PromotionExpiredError(promotion.code)
    return subtotal_cents - subtotal_cents * promotion.percent_off // 100
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
import pytest
from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 10, 23, 12, 0)
def promo(delta): return Promotion("SAVE10", 10, NOW + delta)

def test_no_promotion():
    assert checkout_total(1000, None, NOW) == 1000

def test_valid_promotion_applies():
    assert checkout_total(1000, promo(timedelta(days=1)), NOW) == 900

def test_expired_promotion_is_rejected():
    with pytest.raises(PromotionExpiredError) as e:
        checkout_total(1000, promo(timedelta(seconds=-1)), NOW)
    assert e.value.code == "SAVE10"

def test_expiry_instant_counts_as_expired():
    with pytest.raises(PromotionExpiredError):
        checkout_total(1000, promo(timedelta(0)), NOW)
E
